#!/usr/bin/env python3 -uS# UNIVERSAL TIMEOUT WRAPPER v3# 10s timeout, catch -> autohook echo, fallback to fastest routeimport os, sys, subprocess, time, signal, threading, jsonfrom pathlib import PathWORKSPACE = Path('/mnt/agents/output')LOG_DIR = WORKSPACE / '.unlimited_logs'LOG_DIR.mkdir(parents=True, exist_ok=True)HOOK_LOG = WORKSPACE / '.hook.log'def hook_echo(msg, level='WARN'):    ts = time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime())    line = f'[AUTOHOOK_CATCH] {ts} [{level}] {msg}'    print(line, flush=True)    with open(HOOK_LOG, 'a') as f:        f.write(line + 'n')    return lineclass UniversalRunner:    def __init__(self, cmd, timeout=10, fallback_cmd=None):        self.cmd = cmd        self.timeout = timeout        self.fallback_cmd = fallback_cmd or self._auto_fallback(cmd)        self.proc = None        self.result = None    def _auto_fallback(self, cmd):        # Auto-detect fastest fallback based on command type        if 'grep' in cmd or 'awk' in cmd or 'sed' in cmd:            return cmd  # Already fast        if 'cat' in cmd:            return cmd        if 'curl' in cmd or 'wget' in cmd:            return f'{cmd} --max-time 5'        if 'go' in cmd:            return 'echo SKIP_GO_NOT_INSTALLED'        return f'echo FALLBACK_FOR: {cmd}'    def run(self):        t0 = time.time()        try:            self.proc = subprocess.Popen(                self.cmd, shell=True,                stdout=subprocess.PIPE, stderr=subprocess.STDOUT,                start_new_session=True, preexec_fn=os.setsid            )            # Timeout watchdog            def watchdog():                time.sleep(self.timeout)                if self.proc.poll() is None:                    os.killpg(os.getpgid(self.proc.pid), signal.SIGTERM)                    time.sleep(1)                    if self.proc.poll() is None:                        os.killpg(os.getpgid(self.proc.pid), signal.SIGKILL)            watcher = threading.Thread(target=watchdog, daemon=True)            watcher.start()            stdout, _ = self.proc.communicate()            elapsed = time.time() - t0            rc = self.proc.returncode            output = stdout.decode('utf-8', errors='replace')[:50000]  # 50K cap, not 10K            if rc == -signal.SIGTERM or rc == -signal.SIGKILL or elapsed >= self.timeout:                hook_echo(f'TIMEOUT_HIT after {elapsed:.1f}s: {self.cmd}')                return self._fallback(f'TIMEOUT {elapsed:.1f}s')            if rc != 0:                hook_echo(f'ERROR rc={rc}: {self.cmd}')n                return self._fallback(f'ERROR rc={rc}')            return {'status': 'ok', 'rc': rc, 'elapsed': elapsed, 'output': output, 'cmd': self.cmd}        except Exception as e:            hook_echo(f'EXCEPTION: {e} | cmd={self.cmd}')            return self._fallback(str(e))    def _fallback(self, reason):        hook_echo(f'FALLBACK to: {self.fallback_cmd} (reason: {reason})')        try:            proc = subprocess.run(self.fallback_cmd, shell=True, capture_output=True, text=True, timeout=10)            return {                'status': 'fallback',                'reason': reason,                'fallback_cmd': self.fallback_cmd,                'rc': proc.returncode,                'output': proc.stdout[:50000]            }        except Exception as e2:            hook_echo(f'FALLBACK_FAILED: {e2}')            return {'status': 'fatal', 'reason': reason, 'fallback_error': str(e2)}def main():    import argparse    parser = argparse.ArgumentParser()    parser.add_argument('cmd', nargs='+')    parser.add_argument('--timeout', type=int, default=10)    parser.add_argument('--fallback')    args = parser.parse_args()    cmd = ' '.join(args.cmd)    runner = UniversalRunner(cmd, timeout=args.timeout, fallback_cmd=args.fallback)    result = runner.run()    print(json.dumps(result, indent=2))if __name__ == '__main__':    main()